<?php
/** One owner-facing DID editor. Native destination/dialplan rows are generated by pbx_admin. */
class pbx_did_routes {
    public const VERSION='1.0.23';
    private PDO $db;
    private string $domain;
    private string $actor;
    public function __construct(?PDO $db=null){$this->db=$db??database::new()->db;$this->domain=(string)($_SESSION['domain_uuid']??'');$this->actor=(string)($_SESSION['user_uuid']??'');$this->owner();}
    private function owner(): void {if($this->domain!==($_SESSION['domain_uuid']??null)||$this->actor!==($_SESSION['user_uuid']??null))throw new RuntimeException('Open this PBX again before editing its numbers.');new pbx_trunk_routes($this->db);}
    private function callbacks(): array {
        $s=$this->db->prepare('select service_uuid,incoming_rule_uuid,name,enabled,prompt_state,prompt_version,prompt_sha256,route_owner,updated_at from v_pbx_cmb_services where domain_uuid=:d order by name,service_uuid');$s->execute(['d'=>$this->domain]);return $s->fetchAll(PDO::FETCH_ASSOC);
    }
    public static function number(string $number): string {
        if(strlen($number)>60||!preg_match('/^[+0-9 ()-]+$/D',$number))throw new InvalidArgumentException('Enter a telephone number, for example 0800014509.');
        $number=str_replace([' ','(',')','-'],'',$number);if(str_starts_with($number,'00'))$number='+'.substr($number,2);
        if(!preg_match('/^\+?[0-9]{3,20}$/D',$number))throw new InvalidArgumentException('Enter a telephone number with 3 to 20 digits.');return $number;
    }
    /** Recognize local/international forms only for an explicitly configured numbering country. */
    public static function numberForms(string $number,array $c): array {
        $forms=[$number];
        if((string)($c['country_calling_code']??'')==='27'){
            if(preg_match('/^0([1-9][0-9]{8})$/D',$number,$m))$forms[]='+27'.$m[1];
            elseif(preg_match('/^\+?27([1-9][0-9]{8})$/D',$number,$m))$forms[]='0'.$m[1];
        }
        return array_values(array_unique($forms));
    }
    public static function revision(array $c,?array $rule,?array $callback): string {
        $providers=[];foreach($c['trunks']as$id=>$t)$providers[$id]=array_intersect_key($t,array_flip(['gateway_uuid','enabled','main_number','dids','source_field','allowed_ips']));
        return hash('sha256',json_encode([$rule,$callback,$providers,$c['country_calling_code']??null],JSON_THROW_ON_ERROR));
    }
    public function editor(string $key='new',string $trunk=''): array {
        $this->owner();$c=(new pbx_admin($this->db))->config();$rule=null;$callback=null;$services=$this->callbacks();
        if($key!=='new')foreach($c['inbound_rules']as$r)if(($r['rule_id']??'')===$key){$rule=$r;break;}
        if($key!=='new'&&!$rule)throw new InvalidArgumentException('Choose a number from this PBX.');
        $revision=self::revision($c,$rule,null);
        $choices=[];if($rule)foreach($services as$s)if($s['incoming_rule_uuid']===$key){$callback=$s;$choices[$s['service_uuid']]=$s['name'].($s['prompt_state']==='ready'?'':' · Greeting needs attention');}
        if($rule)$revision=self::revision($c,$rule,$callback);
        if(!$rule){if($trunk!==''&&!isset($c['trunks'][$trunk]))throw new InvalidArgumentException('Choose a provider from this PBX.');$rule=['rule_id'=>'new','number'=>'','name'=>'','trunk_id'=>$trunk,'condition'=>'BasedOnDID','office'=>['type'=>'None','number'=>'','external'=>''],'outside'=>['type'=>'None','number'=>'','external'=>''],'holiday'=>['type'=>'None','number'=>'','external'=>''],'enabled'=>false,'use_outside'=>false,'use_holiday'=>false,'hours'=>['type'=>'AllHours','periods'=>[]]];}
        $destination=$callback&&!empty($callback['enabled'])?'CallMeBack:'.$callback['service_uuid']:($rule['office']['type']??'None').':'.($rule['office']['number']??'');
        $rule['destination']=$destination;$rule['hours_mode']=!empty($rule['use_outside'])?'office':'always';
        return ['config'=>$c,'rule'=>$rule,'revision'=>$revision,'callbacks'=>$choices,'callback'=>$callback,'destination'=>$destination];
    }
    public function listing(): array {
        $this->owner();$c=(new pbx_admin($this->db))->config();$services=[];foreach($this->callbacks()as$s)$services[$s['incoming_rule_uuid']]=$s;$rows=[];
        foreach($c['inbound_rules']as$r){$s=$services[$r['rule_id']]??null;$current=pbx_trunk_routes::current($r,$c);if($s&&!empty($s['enabled']))$current=['slot'=>'callback','label'=>'Call Me Back · '.$s['name']];$rows[]=['rule'=>$r,'callback'=>$s,'current'=>$current,'revision'=>self::revision($c,$r,$s)];}
        usort($rows,static fn($a,$b)=>[($a['rule']['condition']??'')==='ForwardAll',($a['rule']['number']??''),$a['rule']['rule_id']]<=>[($b['rule']['condition']??'')==='ForwardAll',($b['rule']['number']??''),$b['rule']['rule_id']]);return ['config'=>$c,'rows'=>$rows];
    }
    public function save(string $key,array $in): string {$this->owner();return (new pbx_admin($this->db))->saveDid($key,$in);}
}
